const LIKERT5 = ["#10b981","#34d399","#fbbf24","#f97316","#ef4444"];
const LIKERT7 = ["#10b981","#34d399","#fbbf24","#f97316","#ef4444","#94a3b8","#cbd5e1"];
const CAT_SHORT = {"Técnicos-administrativos":"TAs","Coordenadores de Polo":"Coord.","Tutores":"Tutores","Docentes":"Docentes","Discentes Pós":"Disc. Pós","Discente Presencial":"Disc. Pres.","Discentes EaD":"Disc. EaD"};

const THEMES = {
  dark: {
    bg: "#0a0e1a", sidebar: "#0d1117", card: "#0f172a", cardDeep: "#0d1117",
    border: "#1e293b", borderHover: "#334155", grid: "#1e293b", axis: "#334155",
    text: "#e2e8f0", textSec: "#94a3b8", textMuted: "#64748b", textDim: "#334155",
    tooltipBg: "#1e293b", tooltipBorder: "#334155",
    scrollTrack: "#0f172a", scrollThumb: "#334155",
    navActive: "linear-gradient(135deg,#1e3a5f,#1a1a2e)", navActiveBorder: "#1e40af44",
    filterBg: "#0f172a", filterBorder: "#334155", filterActive: "#1e40af", filterActiveBorder: "#3b82f6",
    toggleActive: "#065f46", toggleActiveBorder: "#10b981", toggleActiveText: "#a7f3d0",
    kpi1: {grad:"#1e3a5f,#0f172a",accent:"#60a5fa",brd:"#1e40af33"},
    kpi2: {grad:"#064e3b,#0f172a",accent:"#34d399",brd:"#10b98133"},
    kpi3: {grad:"#3b0764,#0f172a",accent:"#a78bfa",brd:"#8b5cf633"},
  },
  light: {
    bg: "#f1f5f9", sidebar: "#ffffff", card: "#ffffff", cardDeep: "#f8fafc",
    border: "#e2e8f0", borderHover: "#cbd5e1", grid: "#e2e8f0", axis: "#cbd5e1",
    text: "#1e293b", textSec: "#475569", textMuted: "#94a3b8", textDim: "#cbd5e1",
    tooltipBg: "#ffffff", tooltipBorder: "#e2e8f0",
    scrollTrack: "#f1f5f9", scrollThumb: "#cbd5e1",
    navActive: "linear-gradient(135deg,#dbeafe,#ede9fe)", navActiveBorder: "#3b82f644",
    filterBg: "#f8fafc", filterBorder: "#e2e8f0", filterActive: "#3b82f6", filterActiveBorder: "#60a5fa",
    toggleActive: "#10b981", toggleActiveBorder: "#34d399", toggleActiveText: "#ffffff",
    kpi1: {grad:"#dbeafe,#f1f5f9",accent:"#2563eb",brd:"#3b82f633"},
    kpi2: {grad:"#d1fae5,#f1f5f9",accent:"#059669",brd:"#10b98133"},
    kpi3: {grad:"#ede9fe,#f1f5f9",accent:"#7c3aed",brd:"#8b5cf633"},
  }
};

function posRate(s) {
  if (s.scaleType === "profile" || s.scaleType === "yesno") return null;
  const t = s.totals, sum = t.reduce((a,b)=>a+b,0);
  return sum ? Math.round(((t[0]+t[1])/sum)*100) : 0;
}

function Overview({t}) {
  const likert = SHEETS.filter(s=>s.scaleType!=="profile"&&s.scaleType!=="yesno");
  const rankings = likert.map(s=>({id:s.id,rate:posRate(s)})).filter(r=>r.rate!==null).sort((a,b)=>b.rate-a.rate);
  const top5=rankings.slice(0,5), bot5=rankings.slice(-5).reverse();
  const avg = Math.round(rankings.reduce((a,r)=>a+r.rate,0)/rankings.length);

  const secAvgs = SECTIONS.filter(s=>s.sheets.length>0&&s.name!=="Perfil"&&s.name!=="Questionário").map(sec=>{
    const ss=SHEETS.filter(s=>sec.sheets.includes(s.id)&&s.scaleType!=="profile"&&s.scaleType!=="yesno");
    if(!ss.length) return null;
    return {name:sec.name,icon:sec.icon,avg:Math.round(ss.reduce((a,s)=>a+posRate(s),0)/ss.length)};
  }).filter(Boolean).sort((a,b)=>b.avg-a.avg);

  const kpis=[{label:"Respondentes",val:"237",sub:"7 categorias",...t.kpi1},
    {label:"Avaliação Positiva",val:`${avg}%`,sub:"Ótimo + Bom",...t.kpi2},
    {label:"Questões",val:"53",sub:"12 eixos temáticos",...t.kpi3}];

  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:16,marginBottom:28}}>
        {kpis.map((c,i)=>(
          <div key={i} style={{background:`linear-gradient(135deg,${c.grad})`,borderRadius:16,padding:24,border:`1px solid ${c.brd}`}}>
            <div style={{fontSize:12,color:c.accent,letterSpacing:1,textTransform:"uppercase"}}>{c.label}</div>
            <div style={{fontSize:38,fontWeight:800,color:t.text,letterSpacing:-1}}>{c.val}</div>
            <div style={{fontSize:12,color:t.textMuted}}>{c.sub}</div>
          </div>
        ))}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:20,marginBottom:28}}>
        <div style={{background:t.card,borderRadius:16,padding:20,border:`1px solid ${t.border}`}}>
          <h3 style={{fontSize:14,fontWeight:700,color:"#34d399",marginBottom:12}}>🏆 Melhor Avaliadas</h3>
          {top5.map((r,i)=><div key={r.id} style={{display:"flex",alignItems:"center",gap:10,marginBottom:8,padding:"7px 12px",background:t.cardDeep,borderRadius:10,border:`1px solid ${t.border}`}}>
            <span style={{fontSize:20,fontWeight:800,color:"#10b981",minWidth:28}}>{i+1}</span>
            <span style={{flex:1,fontSize:12,color:t.text}}>{r.id}</span>
            <span style={{fontSize:16,fontWeight:800,color:"#10b981"}}>{r.rate}%</span>
          </div>)}
        </div>
        <div style={{background:t.card,borderRadius:16,padding:20,border:`1px solid ${t.border}`}}>
          <h3 style={{fontSize:14,fontWeight:700,color:"#f97316",marginBottom:12}}>⚠️ Pontos de Atenção</h3>
          {bot5.map((r,i)=><div key={r.id} style={{display:"flex",alignItems:"center",gap:10,marginBottom:8,padding:"7px 12px",background:t.cardDeep,borderRadius:10,border:`1px solid ${t.border}`}}>
            <span style={{fontSize:20,fontWeight:800,color:"#f97316",minWidth:28}}>{i+1}</span>
            <span style={{flex:1,fontSize:12,color:t.text}}>{r.id}</span>
            <span style={{fontSize:16,fontWeight:800,color:"#f97316"}}>{r.rate}%</span>
          </div>)}
        </div>
      </div>
      <div style={{background:t.card,borderRadius:16,padding:20,border:`1px solid ${t.border}`}}>
        <h3 style={{fontSize:14,fontWeight:700,color:"#60a5fa",marginBottom:14}}>📈 Avaliação por Eixo Temático</h3>
        <ResponsiveContainer width="100%" height={340}>
          <BarChart data={secAvgs} layout="vertical" margin={{left:10,right:30}}>
            <CartesianGrid strokeDasharray="3 3" stroke={t.grid}/>
            <XAxis type="number" domain={[0,100]} tick={{fill:t.textSec,fontSize:11}} axisLine={{stroke:t.axis}}/>
            <YAxis type="category" dataKey="name" tick={{fill:t.text,fontSize:12}} width={120} axisLine={{stroke:t.axis}}/>
            <Tooltip contentStyle={{background:t.tooltipBg,border:`1px solid ${t.tooltipBorder}`,borderRadius:8,color:t.text,fontSize:12}} formatter={v=>`${v}%`}/>
            <Bar dataKey="avg" radius={[0,6,6,0]}>{secAvgs.map((s,i)=><Cell key={i} fill={s.avg>=60?"#10b981":s.avg>=40?"#fbbf24":"#ef4444"}/>)}</Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function MultiChart({ sheet, showPct, selectedCats, viewMode, t }) {
  const colors = sheet.options.length <= 2 ? ["#10b981","#ef4444"] : sheet.options.length > 5 ? LIKERT7 : LIKERT5;
  const labels = sheet.options.map(o => o.replace(/^[A-G]\.\s*/, ""));
  const ttStyle = {background:t.tooltipBg,border:`1px solid ${t.tooltipBorder}`,borderRadius:8,color:t.text,fontSize:12};

  if (viewMode === "TOTAL") {
    const total = sheet.totals.reduce((a,b)=>a+b,0);
    const pie = labels.map((l,i) => ({ name: l, value: sheet.totals[i], pct: total ? Math.round(sheet.totals[i]/total*1000)/10 : 0 })).filter(d=>d.value>0);
    return (
      <div style={{display:"flex",flexDirection:"column",alignItems:"center"}}>
        <ResponsiveContainer width="100%" height={240}>
          <PieChart><Pie data={pie} cx="50%" cy="50%" outerRadius={90} innerRadius={45} dataKey="value" paddingAngle={2} label={({name,pct})=>`${name}: ${pct}%`} labelLine={{stroke:t.textMuted}} style={{fontSize:10}}>
            {pie.map((_,i)=><Cell key={i} fill={colors[labels.indexOf(pie[i].name)]||colors[i%colors.length]}/>)}
          </Pie><Tooltip contentStyle={ttStyle}/></PieChart>
        </ResponsiveContainer>
        <div style={{display:"flex",flexWrap:"wrap",gap:8,justifyContent:"center",marginTop:4}}>
          {labels.map((l,i)=><span key={i} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,color:t.textSec}}><span style={{width:8,height:8,borderRadius:"50%",background:colors[i]}}/>{l}: <b style={{color:t.text}}>{sheet.totals[i]}</b></span>)}
        </div>
      </div>
    );
  }

  if (viewMode === "COMBINED" && selectedCats.length > 0) {
    const indices = selectedCats.map(c => sheet.categories.indexOf(c)).filter(i => i >= 0);
    const combined = labels.map((l, oi) => indices.reduce((a, ci) => a + sheet.absValues[ci][oi], 0));
    const combTotal = combined.reduce((a,b)=>a+b,0);
    if (showPct) {
      const pie = labels.map((l,i) => ({ name: l, value: combined[i], pct: combTotal ? Math.round(combined[i]/combTotal*1000)/10 : 0 })).filter(d=>d.value>0);
      return (
        <div style={{display:"flex",flexDirection:"column",alignItems:"center"}}>
          <div style={{fontSize:11,color:t.textMuted,marginBottom:6}}>Agregado: {selectedCats.map(c=>CAT_SHORT[c]||c).join(" + ")} (n={combTotal})</div>
          <ResponsiveContainer width="100%" height={240}>
            <PieChart><Pie data={pie} cx="50%" cy="50%" outerRadius={90} innerRadius={45} dataKey="value" paddingAngle={2} label={({name,pct})=>`${name}: ${pct}%`} labelLine={{stroke:t.textMuted}} style={{fontSize:10}}>
              {pie.map((_,i)=><Cell key={i} fill={colors[labels.indexOf(pie[i].name)]||colors[i%colors.length]}/>)}
            </Pie><Tooltip contentStyle={ttStyle}/></PieChart>
          </ResponsiveContainer>
          <div style={{display:"flex",flexWrap:"wrap",gap:8,justifyContent:"center",marginTop:4}}>
            {labels.map((l,i)=><span key={i} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,color:t.textSec}}><span style={{width:8,height:8,borderRadius:"50%",background:colors[i]}}/>{l}: <b style={{color:t.text}}>{combined[i]}</b> ({combTotal?Math.round(combined[i]/combTotal*1000)/10:0}%)</span>)}
          </div>
        </div>
      );
    }
  }

  const catsToShow = selectedCats.filter(c => sheet.categories.includes(c));
  if (catsToShow.length === 0) return <div style={{color:t.textMuted,fontSize:12,padding:20,textAlign:"center"}}>Selecione ao menos um segmento</div>;

  const data = catsToShow.map((cat) => {
    const ci = sheet.categories.indexOf(cat);
    return {name:CAT_SHORT[cat]||cat,...Object.fromEntries(labels.map((l,oi)=>[l,showPct?sheet.pctValues[ci][oi]:sheet.absValues[ci][oi]]))};
  });

  return (
    <ResponsiveContainer width="100%" height={Math.max(160, catsToShow.length * 44 + 60)}>
      <BarChart data={data} margin={{top:5,right:10,left:0,bottom:5}}>
        <CartesianGrid strokeDasharray="3 3" stroke={t.grid}/>
        <XAxis dataKey="name" tick={{fill:t.textSec,fontSize:11}} axisLine={{stroke:t.axis}}/>
        <YAxis tick={{fill:t.textSec,fontSize:11}} axisLine={{stroke:t.axis}}/>
        <Tooltip contentStyle={ttStyle}/>
        {labels.map((l,i)=><Bar key={l} dataKey={l} stackId="a" fill={colors[i]} radius={i===labels.length-1?[3,3,0,0]:undefined}/>)}
      </BarChart>
    </ResponsiveContainer>
  );
}

const CAT_COLORS = {"Técnicos-administrativos":"#60a5fa","Coordenadores de Polo":"#f472b6","Tutores":"#a78bfa","Docentes":"#34d399","Discentes Pós":"#fbbf24","Discente Presencial":"#fb923c","Discentes EaD":"#38bdf8"};

export default function Dashboard() {
  const [sec,setSec]=useState(0);
  const [pct,setPct]=useState(true);
  const [selectedCats,setSelectedCats]=useState(SHEETS[0].categories.slice());
  const [viewMode,setViewMode]=useState("TOTAL");
  const [open,setOpen]=useState(true);
  const [dark,setDark]=useState(true);
  const t=THEMES[dark?"dark":"light"];
  const allCats=SHEETS[0].categories;
  const cur=sec===0?[]:SHEETS.filter(s=>SECTIONS[sec].sheets.includes(s.id));

  const toggleCat=(c)=>{
    setSelectedCats(prev=>prev.includes(c)?prev.filter(x=>x!==c):[...prev,c]);
    if(viewMode==="TOTAL") setViewMode("COMPARE");
  };
  const selectAll=()=>setSelectedCats(allCats.slice());
  const selectNone=()=>setSelectedCats([]);

  return (
    <div style={{display:"flex",minHeight:"100vh",background:t.bg,fontFamily:"'Source Sans 3','Segoe UI',system-ui,sans-serif",color:t.text,transition:"background .3s,color .3s"}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@300;400;600;700;800;900&display=swap');*{box-sizing:border-box;margin:0;padding:0}::-webkit-scrollbar{width:6px}::-webkit-scrollbar-track{background:${t.scrollTrack}}::-webkit-scrollbar-thumb{background:${t.scrollThumb};border-radius:3px}.nb{cursor:pointer;transition:all .2s;border:none;background:transparent;text-align:left;width:100%;padding:10px 14px;border-radius:10px;display:flex;align-items:center;gap:10px;color:${t.textSec};font-size:13px;font-family:inherit}.nb:hover{background:${t.border};color:${t.text}}.nb.a{background:${t.navActive};color:#60a5fa;font-weight:700;border:1px solid ${t.navActiveBorder}}.fb{cursor:pointer;transition:all .15s;border:1px solid ${t.filterBorder};background:${t.filterBg};color:${t.textSec};padding:6px 14px;border-radius:20px;font-size:12px;font-family:inherit;white-space:nowrap}.fb:hover{border-color:#60a5fa;color:${t.text}}.fb.a{background:${t.filterActive};border-color:${t.filterActiveBorder};color:#fff;font-weight:600}.tb{cursor:pointer;border:1px solid ${t.filterBorder};background:${t.filterBg};color:${t.textSec};padding:6px 14px;border-radius:20px;font-size:12px;font-family:inherit;transition:all .15s}.tb.a{background:${t.toggleActive};border-color:${t.toggleActiveBorder};color:${t.toggleActiveText};font-weight:600}.cd{background:${t.card};border:1px solid ${t.border};border-radius:16px;padding:20px;margin-bottom:16px;transition:border-color .2s,background .3s}.cd:hover{border-color:${t.borderHover}}.hm{display:none;cursor:pointer;background:${t.card};border:1px solid ${t.border};color:${t.text};padding:8px 12px;border-radius:8px;position:fixed;top:12px;left:12px;z-index:100;font-size:18px;font-family:inherit}.ck{cursor:pointer;display:flex;align-items:center;gap:6px;padding:5px 12px;border-radius:20px;font-size:12px;font-family:inherit;transition:all .15s;border:1px solid ${t.filterBorder};background:${t.filterBg};color:${t.textSec};white-space:nowrap;user-select:none}.ck:hover{border-color:#60a5fa;color:${t.text}}.ck.a{border-color:var(--accent);color:${dark?"#fff":"#1e293b"};background:color-mix(in srgb,var(--accent) ${dark?"25%":"18%"},${t.filterBg})}.ck .dot{width:8px;height:8px;border-radius:50%;border:2px solid ${t.textMuted};transition:all .15s;flex-shrink:0}.ck.a .dot{background:var(--accent);border-color:var(--accent);box-shadow:0 0 6px var(--accent)}.thsw{display:flex;align-items:center;gap:6px;cursor:pointer;background:${t.card};border:1px solid ${t.border};padding:5px 12px;border-radius:20px;font-size:11px;font-family:inherit;color:${t.textSec};transition:all .2s;white-space:nowrap}.thsw:hover{border-color:#60a5fa;color:${t.text}}@media(max-width:900px){.hm{display:block}.sb{position:fixed!important;z-index:99;transform:translateX(-100%);transition:transform .3s}.sb.o{transform:translateX(0)}.mc{margin-left:0!important;padding-top:52px!important}}`}</style>
      <button className="hm" onClick={()=>setOpen(!open)}>☰</button>
      <div className={`sb ${open?"o":""}`} style={{width:240,minWidth:240,background:t.sidebar,borderRight:`1px solid ${t.border}`,padding:"20px 12px",position:"sticky",top:0,height:"100vh",overflowY:"auto",transition:"background .3s"}}>
        <div style={{padding:"0 8px 16px",borderBottom:`1px solid ${t.border}`,marginBottom:12}}>
          <h1 style={{fontSize:18,fontWeight:900,background:"linear-gradient(135deg,#60a5fa,#a78bfa)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>CPA/INES: Painel de Dados do RAAI 2026</h1>
          <p style={{fontSize:11,color:t.textMuted,marginTop:2}}>Relatório Integral</p>
        </div>
        <div style={{padding:"0 4px 14px",borderBottom:`1px solid ${t.border}`,marginBottom:12}}>
          <button className="thsw" onClick={()=>setDark(!dark)} style={{width:"100%",justifyContent:"center"}}>
            {dark?"☀️ Modo Claro":"🌙 Modo Escuro"}
          </button>
        </div>
        {SECTIONS.map((s,i)=><button key={i} className={`nb ${sec===i?"a":""}`} onClick={()=>{setSec(i);if(window.innerWidth<900)setOpen(false)}}>
          <span style={{fontSize:16}}>{s.icon}</span><span>{s.name}</span>
          {s.sheets.length>0&&<span style={{marginLeft:"auto",fontSize:10,background:t.border,padding:"2px 6px",borderRadius:8,color:t.textMuted}}>{s.sheets.length}</span>}
        </button>)}
      </div>
      <div className="mc" style={{flex:1,padding:28,overflowY:"auto"}}>
        <div style={{maxWidth:1100,margin:"0 auto"}}>
          <div style={{marginBottom:24}}>
            <h2 style={{fontSize:26,fontWeight:800,letterSpacing:-.5,color:t.text}}>{SECTIONS[sec].icon} {SECTIONS[sec].name}</h2>
            {sec>0&&<p style={{fontSize:13,color:t.textMuted,marginTop:4}}>{SECTIONS[sec].sheets.length} questões</p>}
          </div>
          {sec>0&&<div style={{background:t.cardDeep,border:`1px solid ${t.border}`,borderRadius:16,padding:16,marginBottom:20,transition:"background .3s"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
              <span style={{fontSize:13,fontWeight:700,color:t.textSec}}>Visualização</span>
              <div style={{display:"flex",gap:6}}>
                <button className={`tb ${pct?"a":""}`} onClick={()=>setPct(true)}>%</button>
                <button className={`tb ${!pct?"a":""}`} onClick={()=>setPct(false)}>n</button>
              </div>
            </div>
            <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:12}}>
              <button className={`fb ${viewMode==="TOTAL"?"a":""}`} onClick={()=>setViewMode("TOTAL")}>Total Geral</button>
              <button className={`fb ${viewMode==="COMPARE"?"a":""}`} onClick={()=>setViewMode("COMPARE")}>Comparar</button>
              <button className={`fb ${viewMode==="COMBINED"?"a":""}`} onClick={()=>setViewMode("COMBINED")}>Agregar</button>
            </div>
            {viewMode!=="TOTAL"&&<div>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                <span style={{fontSize:11,color:t.textMuted}}>Segmentos:</span>
                <button style={{fontSize:10,color:"#60a5fa",background:"none",border:"none",cursor:"pointer",fontFamily:"inherit",padding:0}} onClick={selectAll}>Todos</button>
                <span style={{color:t.textDim,fontSize:10}}>|</span>
                <button style={{fontSize:10,color:"#60a5fa",background:"none",border:"none",cursor:"pointer",fontFamily:"inherit",padding:0}} onClick={selectNone}>Nenhum</button>
                <span style={{marginLeft:8,fontSize:10,color:t.textMuted}}>{selectedCats.length} de {allCats.length} selecionados</span>
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                {allCats.map(c=><button key={c} className={`ck ${selectedCats.includes(c)?"a":""}`} style={{"--accent":CAT_COLORS[c]||"#60a5fa"}} onClick={()=>toggleCat(c)}>
                  <span className="dot"/>{CAT_SHORT[c]||c}
                </button>)}
              </div>
            </div>}
          </div>}
          {sec===0&&<Overview t={t}/>}
          {sec>0&&cur.map(s=><div key={s.id} className="cd">
            <h3 style={{fontSize:14,fontWeight:700,color:t.text,marginBottom:4}}>{s.id}</h3>
            <p style={{fontSize:12,color:t.textMuted,lineHeight:1.5,marginBottom:8}}>{s.question}</p>
            {posRate(s)!==null&&<div style={{display:"inline-flex",alignItems:"center",gap:6,marginBottom:12,background:t.cardDeep,padding:"4px 10px",borderRadius:20,border:`1px solid ${t.border}`}}>
              <span style={{fontSize:11,color:t.textMuted}}>Positiva:</span>
              <span style={{fontSize:14,fontWeight:800,color:posRate(s)>=60?"#10b981":posRate(s)>=40?"#fbbf24":"#ef4444"}}>{posRate(s)}%</span>
            </div>}
            <MultiChart sheet={s} showPct={pct} selectedCats={selectedCats} viewMode={viewMode} t={t}/>
          </div>)}
          <div style={{textAlign:"center",padding:"30px 0 10px",fontSize:11,color:t.textDim}}>RAAI · Dashboard Interativo · Relatório Integral · v2.1</div>
        </div>
      </div>
    </div>
  );
}
